import calendar
from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _add_months(year: int, month: int, n: int) -> tuple[int, int]:
    total = year * 12 + (month - 1) + n
    return total // 12, total % 12 + 1


def _nth_weekday(year: int, month: int, n: int, wd: int):
    if n == -1:
        last = date(year, month, calendar.monthrange(year, month)[1])
        return last - timedelta(days=(last.weekday() - wd) % 7)
    first = date(year, month, 1)
    day = 1 + (wd - first.weekday()) % 7 + (n - 1) * 7
    if day > calendar.monthrange(year, month)[1]:
        return None
    return date(year, month, day)


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = (int(p) for p in start.split("-"))
    cur = date(y, m, d)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    out: list[date] = []

    if kind == "DAILY":
        out = [cur + timedelta(days=i * k) for i in range(count)]
    elif kind == "WEEKLY":
        days = sorted(_WD[c] for c in parts[2].split(","))
        monday = cur - timedelta(days=cur.weekday())
        i = 0
        while len(out) < count:
            week = monday + timedelta(days=7 * i * k)
            for wd in days:
                dt = week + timedelta(days=wd)
                if dt >= cur:
                    out.append(dt)
                    if len(out) == count:
                        break
            i += 1
    elif kind == "MONTHLY" and len(parts) == 3:
        dom = int(parts[2])
        i = 0
        while len(out) < count:
            ty, tm = _add_months(cur.year, cur.month, i * k)
            last = calendar.monthrange(ty, tm)[1]
            dt = None
            if dom == -1:
                dt = date(ty, tm, last)
            elif dom <= last:
                dt = date(ty, tm, dom)
            if dt is not None and dt >= cur:
                out.append(dt)
            i += 1
    elif kind == "MONTHLY":
        n = int(parts[2])
        wd = _WD[parts[3]]
        i = 0
        while len(out) < count:
            ty, tm = _add_months(cur.year, cur.month, i * k)
            dt = _nth_weekday(ty, tm, n, wd)
            if dt is not None and dt >= cur:
                out.append(dt)
            i += 1
    else:
        mm, dd = (int(p) for p in parts[2].split("-"))
        i = 0
        while len(out) < count:
            try:
                dt = date(cur.year + i * k, mm, dd)
            except ValueError:
                dt = None
            if dt is not None and dt >= cur:
                out.append(dt)
            i += 1

    return [dt.isoformat() for dt in out]
